from review import card,save,DATE
i='TCS-3580';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 5, limitations of the irrelevant vertex technique; Theorems 1–2 and Section 2 graph conventions.'
refs += [dict(id='full',title='k-apices of minor-closed graph classes. II. Parameterized algorithms',authors='Ignasi Sau; Giannos Stamoulis; Dimitrios M. Thilikos',year=2021,url='https://arxiv.org/abs/2004.12692',pdf_url='https://arxiv.org/pdf/2004.12692',locator='Full preprint version 2, 2 March 2021, concluding remarks; repeats the class-dependent exponent and conditional-lower-bound questions.'),dict(id='quadratic',title='Faster parameterized algorithms for modification problems to minor-closed classes',authors='Laure Morelle; Ignasi Sau; Giannos Stamoulis; Dimitrios M. Thilikos',year=2024,url='https://doi.org/10.46298/theoretics.24.19',pdf_url='https://arxiv.org/pdf/2210.02167',locator='TheoretiCS, 12 August 2024; Theorem 1.1 and Section 11, especially page 72: universal exponent remains open and no stronger-than-subexponential ETH lower bound is known to the authors.'),dict(id='replacement',title='Graph Modification of Bounded Size to Minor-Closed Classes as Fast as Vertex Deletion',authors='Laure Morelle; Ignasi Sau; Dimitrios M. Thilikos',year=2025,url='https://doi.org/10.4230/LIPIcs.ESA.2025.7',locator='ESA 2025 abstract: broader replacements retain a class-dependent polynomial degree; genus-bounded targets are a special case.')]
issue='The extracted question asks for a conditional explanation of class dependence, but does not specify whether the lower bound must apply to all algorithms or only a formally defined irrelevant-vertex/homogeneity framework. The latter framework is not defined as a restricted computational model. No particular complexity hypothesis and quantified lower-bound rate are fixed. The surrounding universal-exponent upper-bound question is precise enough to describe the motivation, but is not silently substituted for this lower-bound request.'
notes=['Recovered the missing behavior as dependence of the exponent of k on the fixed excluded-minor class.','Separated deletion budget k, input size n and fixed obstruction size, and distinguished apex vertices from excluding an apex graph.','Updated cubic input dependence to the general quadratic algorithm of 2024 and checked the 2025 replacement generalization.','Retained the unresolved scope of the requested conditional lower bound rather than inventing a restricted-algorithm model or hypothesis.']
save(i,dict(title='Why does the parameter exponent for minor-closed vertex deletion depend on the class?',formal='Can a complexity-theoretic lower bound explain why the degree of the polynomial in the exponent of a 2^{poly(k)}n^{O(1)} algorithm for Vertex Deletion to a fixed minor-closed graph class appears to depend on that class? The source contrasts its class-dependent exponent with a hypothetical bound 2^{C_𝒢 k^d}n^{O(1)}, where d is one universal constant for all fixed classes 𝒢, while C_𝒢 may depend on 𝒢. It then asks whether the observed dependence is unavoidable under a complexity assumption, after discussing limitations of its irrelevant-vertex technique. The intended scope of that conditional lower bound still needs specification.',definitions='Graphs are finite, simple and undirected. A graph minor is obtained by deleting vertices or edges and contracting edges, discarding loops and duplicate edges. A class 𝒢 is minor-closed if it contains every minor of each of its members. For a fixed proper minor-closed class, its finite obstruction family F consists of the graphs outside 𝒢 whose proper minors all belong to 𝒢; membership in 𝒢 means excluding all members of F as minors. Put s_F=max_{H∈F}|V(H)|. The input to Vertex Deletion to 𝒢 is a graph G with n vertices and an integer k≥0. It asks whether some S⊆V(G), |S|≤k, has G−S∈𝒢; the source algorithms also return such an S on yes-instances. The class and its obstruction family are fixed before receiving G,k. They are not extra instance parameters hidden in n. A graph satisfying the deletion condition is a k-apex of 𝒢. Separately, an apex graph is one that becomes planar after deleting at most one vertex; the assumption that F contains an apex graph describes only a special collection of target classes. In the proposed universal-exponent scale, multiplicative constants inside the exponential can depend on the target class, but the degree d cannot. A result that improves only the polynomial factor in n does not remove the dependence of d on the class. The irrelevant-vertex method repeatedly deletes vertices proved not to change the answer; the source uses homogeneous wall structures to justify such deletions. This methodological description is not a formal restriction on every permissible algorithm.',question_type='yes_no',answer_criterion='Specify a recognized complexity assumption and an exact lower-bound statement that rules out the proposed universal degree across fixed target classes, or precisely define and prove the claimed limitation of the irrelevant-vertex framework. These are different scopes. A universal-degree algorithm would refute the unrestricted algorithmic necessity but would not by itself characterize the chosen technique. A lower bound on polynomial kernel size, or on n alone, does not establish the desired running-time dependence on k.',context_blocks=[dict(title='The omitted behavior is now explicit',text='The original algorithms use a polynomial in k whose degree grows with obstruction size. The concluding question is about that degree, rather than the number of vertices to delete or the mere existence of an FPT algorithm.',citation='primary'),dict(title='A newer general upper bound',text='The 2024 article reduces the general input-size factor from n³ to n² while retaining a target-class-dependent polynomial in the exponent. Its conclusion explicitly asks again whether a universal degree can replace that polynomial.',citation='quadratic'),dict(title='Lower bounds remain weaker than the desired explanation',text='The 2024 authors report no ETH lower bound stronger than ruling out subexponential dependence on k for the problems considered. This does not show that the degree must increase across classes. Their stated suspicion particularly concerns their homogeneity construction.',citation='quadratic'),dict(title='A later extension preserves the same issue',text='The ESA 2025 replacement framework includes more graph modifications with the same class-dependent degree. Its universal degree for bounded-genus target classes concerns a restricted family of classes.',citation='replacement')],why='Would distinguish an intrinsic cost of deleting into increasingly general minor-closed classes from the cost of the graph-structure method used by current algorithms.',references=refs,progress=[dict(date='2020',text='The source obtains 2^{poly(k)}n³ time in general and raises the class-dependence question.',citation='primary'),dict(date='2024-08-12',text='The general n factor becomes quadratic, while the universal parameter exponent and stronger conditional lower bounds remain open in Section 11.',citation='quadratic'),dict(date='2025',text='The broader graph-replacement result retains the class-dependent degree for arbitrary minor-closed targets.',citation='replacement')],status='uncertain',status_note='Checked the 2020 question, its 2021 full version, the 2024 journal conclusion and the 2025 replacement result. Searches through 12 September 2026 did not locate the requested conditional explanation. The upper-bound motivation is recovered, but the extracted lower-bound request still leaves its computational scope and hypothesis open.',model_self_contained=False,requires_context=True,statement_review=dict(status='needs_specification',reviewed_on=DATE,notes=notes,remaining_issue=issue),review_note=issue,importance=dict(score=c['importance']['score'],method='editorial',reason='A broad parameter-dependence question for graph-minor deletion algorithms and the reach of structural techniques. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['Deleting at most k vertices should leave a graph in a fixed minor-closed class.','Known general algorithms have a polynomial in k inside an exponential, and its degree depends on the class.','The question seeks a conditional reason why this dependence cannot be avoided.','A 2024 algorithm improves the dependence on graph size but explicitly retains the parameter-exponent question.','The extracted request must still distinguish a lower bound for every algorithm from a limitation of one graph-structure technique.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full','quadratic','replacement'])),notes=notes,checked_sources=[r['url'] for r in refs],state='improved_unfinished')
